import {
  Button,
  Card,
  CardMedia,
  Grid,
  TextField,
  Typography,
  MenuItem,
  FormControl,
  Select,
} from "@mui/material";
import "./App.css";
import { useState } from "react";
import { useFilePicker } from "use-file-picker";
import {
  adaptifEsiklemeRequest,
  binaryRequest,
  blurringRequest,
  brightnessRequest,
  cropImageRequest,
  gaussRequest,
  grayScaleRequest,
  gurultuEklemeRequest,
  gurultuTemizlemeRequest,
  rotateRequest,
  sobelRequest,
  zoomInRequest,
} from "./requests/requests";

function App() {
  const [output, setOutput] = useState();

  const [data, setData] = useState({
    cropX: 2,
    cropY: 2,
    cropA: 200,
    cropB: 200,
    rotateValue: 90,
    brightnessFactor: 1.5,
    zoomInValue: 2,
    zoomInCenterX: 450,
    zoomInCenterY: 450,
    blur_kernel_size: 10,
    gauss_kernel_size: 10,
    gauss_sigma: 5,
    adaptifBlockSize: 15,
    adaptifCValue: 10,
    saltValue: 0.1,
    pepperValue: 0.1,
    gurultuFilterSize: 3,
    gurultuFilterType: "mean",
  });

  const handleChange = (e) => {
    setData({ ...data, [e.target.name]: e.target.value });
  };

  const { openFilePicker, filesContent, plainFiles, clear } = useFilePicker({
    readAs: "DataURL",
    accept: "image/*",
    multiple: false,
  });

  const temizle = () => {
    clear();
    setOutput(null);
  };

  const createFormData = (...entries) => {
    const formData = new FormData();
    formData.append("file", plainFiles[0]);
    entries.forEach(([key, value]) => formData.append(key, value));
    return formData;
  };

  const handleRequest = async (formData, requestFn) => {
    const imageUrl = await requestFn(formData);
    if (imageUrl) setOutput(imageUrl);
  };

  return (
    <Grid container direction="column" alignItems="center" spacing={2}>
      <Typography variant="h4" marginTop={3}>
        Görüntü İşleme Uygulaması
      </Typography>

      <Grid item>
        <Button variant="contained" color="error" onClick={temizle}>
          Temizle
        </Button>
        <Button
          variant="contained"
          color="primary"
          onClick={openFilePicker}
          sx={{ mx: 2 }}
        >
          Resim Yükle
        </Button>
      </Grid>

      <Grid item container justifyContent="center" spacing={3}>
        {filesContent.length > 0 && (
          <Card>
            <CardMedia
              component="img"
              height="300"
              image={filesContent[0].content}
              alt="Yüklenen Görsel"
            />
          </Card>
        )}
        {output && (
          <Card>
            <CardMedia
              component="img"
              height="300"
              image={output}
              alt="İşlenmiş Görsel"
            />
          </Card>
        )}
      </Grid>

      {/* İşlem Butonları ve Değer Girişleri */}
      <Grid container spacing={2} padding={4}>
        {/* Cropping */}
        <Grid item>
          <Button
            onClick={() =>
              handleRequest(
                createFormData([
                  ["x", data.cropX],
                  ["y", data.cropY],
                  ["a", data.cropA],
                  ["b", data.cropB],
                ]),
                cropImageRequest
              )
            }
            variant="contained"
            color="error"
          >
            Cropping
          </Button>
          <TextField
            label="cropX"
            name="cropX"
            value={data.cropX}
            onChange={handleChange}
          />
          <TextField
            label="cropY"
            name="cropY"
            value={data.cropY}
            onChange={handleChange}
          />
          <TextField
            label="cropA"
            name="cropA"
            value={data.cropA}
            onChange={handleChange}
          />
          <TextField
            label="cropB"
            name="cropB"
            value={data.cropB}
            onChange={handleChange}
          />
        </Grid>

        {/* Grayscale */}
        <Grid item>
          <Button
            onClick={() =>
              handleRequest(createFormData([]), grayScaleRequest)
            }
            variant="contained"
            color="error"
          >
            Grayscale
          </Button>
        </Grid>

        {/* Binary */}
        <Grid item>
          <Button
            onClick={() =>
              handleRequest(createFormData([]), binaryRequest)
            }
            variant="contained"
            color="error"
          >
            Binary
          </Button>
        </Grid>

        {/* Rotate */}
        <Grid item>
          <Button
            onClick={() =>
              handleRequest(
                createFormData([["x", data.rotateValue]]),
                rotateRequest
              )
            }
            variant="contained"
            color="error"
          >
            Rotate
          </Button>
          <TextField
            label="Rotate (derece)"
            name="rotateValue"
            value={data.rotateValue}
            onChange={handleChange}
          />
        </Grid>

        {/* Brightness */}
        <Grid item>
          <Button
            onClick={() =>
              handleRequest(
                createFormData([["x", data.brightnessFactor]]),
                brightnessRequest
              )
            }
            variant="contained"
            color="error"
          >
            Brightness
          </Button>
          <TextField
            label="Parlaklık"
            name="brightnessFactor"
            value={data.brightnessFactor}
            onChange={handleChange}
          />
        </Grid>

        {/* Zoom */}
        <Grid item>
          <Button
            onClick={() =>
              handleRequest(
                createFormData([
                  ["zoom_factor", data.zoomInValue],
                  ["center_x", data.zoomInCenterX],
                  ["center_y", data.zoomInCenterY],
                ]),
                zoomInRequest
              )
            }
            variant="contained"
            color="error"
          >
            Zoom
          </Button>
          <TextField
            label="Zoom Katsayısı"
            name="zoomInValue"
            value={data.zoomInValue}
            onChange={handleChange}
          />
          <TextField
            label="center_x"
            name="zoomInCenterX"
            value={data.zoomInCenterX}
            onChange={handleChange}
          />
          <TextField
            label="center_y"
            name="zoomInCenterY"
            value={data.zoomInCenterY}
            onChange={handleChange}
          />
        </Grid>

        {/* Diğer işlemler de eklenebilir... */}
      </Grid>
    </Grid>
  );
}

export default App;
